using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Windows.Forms;
using MC2Pack;
namespace Astera {
sealed partial class LibraryForm {
    internal static int AuditDiscover(string root){try{
        if(Directory.Exists(root))throw new IOException("Use a new audit directory");Directory.CreateDirectory(root);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var checks=new List<string>();
        var bundled=DiscoverCatalog.Bundled();AuditAssert(bundled.Projects.Count==5&&bundled.Projects.Any(p=>p.Title=="Gacha Nebula +")&&bundled.Projects.Any(p=>p.Id=="last-light"&&p.Status=="coming-soon"),"Bundled catalog mismatch");checks.Add("Curated bundled catalog includes correctly named upcoming projects without fake downloads");
        string json=Engine.Json.Serialize(bundled);using(var rsa=new RSACryptoServiceProvider(2048,new CspParameters(24))){rsa.PersistKeyInCsp=false;byte[] payload=Encoding.UTF8.GetBytes(json);var envelope=new Envelope{Payload=Convert.ToBase64String(payload),Signature=Convert.ToBase64String(rsa.SignData(payload,"SHA256"))};AuditAssert(DiscoverCatalog.Verify(Encoding.UTF8.GetBytes(Engine.Json.Serialize(envelope)),rsa.ToXmlString(false)).Projects.Count==5,"Signed catalog did not verify");payload[5]^=1;envelope.Payload=Convert.ToBase64String(payload);bool rejected=false;try{DiscoverCatalog.Verify(Encoding.UTF8.GetBytes(Engine.Json.Serialize(envelope)),rsa.ToXmlString(false));}catch{rejected=true;}AuditAssert(rejected,"Tampered catalog accepted");}checks.Add("Signed catalog accepts the matching publisher key and refuses modified payloads");
        foreach(string bad in new[]{json.Replace("\"LibraryKind\":-1","\"LibraryKind\":0"),json.Replace("\"Id\":\"star-dash\"","\"Id\":\"minecraft-squared\""),json.Replace("\"OfficialUrl\":\"https://github.com/","\"OfficialUrl\":\"http://github.com/")}){bool rejected=false;try{DiscoverCatalog.Parse(bad);}catch{rejected=true;}AuditAssert(rejected,"Unsafe catalog metadata accepted");}bool invalidImage=false;try{DiscoverCatalog.Image(new CatalogImage{Url="https://example.invalid/art.png",Hash="../../file"});}catch{invalidImage=true;}AuditAssert(invalidImage,"Unsafe image cache key accepted");checks.Add("Duplicate identities, injected install routes, insecure links, and unsafe artwork hashes are refused");
        string imageCache=Path.Combine(root,"art-cache");Directory.CreateDirectory(imageCache);string cachedImage=Path.Combine(root,"cache-fixture.png");using(var bitmap=new Bitmap(40,30)){using(var graphics=Graphics.FromImage(bitmap))graphics.Clear(Color.Teal);bitmap.Save(cachedImage);}string imageHash=Engine.Hash(cachedImage);File.Copy(cachedImage,Path.Combine(imageCache,imageHash.ToLowerInvariant()+".image"));var cachedArt=new CatalogImage{Url="https://example.invalid/never-requested.png",Hash=imageHash};using(var bitmap=DiscoverCatalog.ReadRemoteImage(cachedArt,imageCache,System.Threading.CancellationToken.None))AuditAssert(bitmap.Width==40,"Verified offline artwork cache failed");File.WriteAllText(Path.Combine(imageCache,imageHash.ToLowerInvariant()+".image"),"tampered");using(var stop=new System.Threading.CancellationTokenSource()){stop.Cancel();bool refused=false;try{using(var bad=DiscoverCatalog.ReadRemoteImage(cachedArt,imageCache,stop.Token)){} }catch(OperationCanceledException){refused=true;}AuditAssert(refused,"Tampered cached artwork was accepted");}checks.Add("Artwork cache verifies SHA-256 before reuse and refuses tampered cached bytes without a network request");
        var state=new Store(Path.Combine(root,"state"));state.Settings.AnimatedEffects=false;state.Settings.UseMinecraftSkin=false;state.Settings.CheckOnStart=false;
        using(var form=new LibraryForm(state,new Channel(),true)){
            form.Location=new Point(-30000,-30000);form.Show();Application.DoEvents();form.Refresh();var original=LibraryKey(form.activeLibraryEntry);form.busy=true;form.RefreshView();AuditAssert(!form.status.Visible,"Working status leaked into hero artwork");form.busy=false;form.RefreshView();AuditAssert(form.librarySearch.BorderStyle==BorderStyle.None&&form.discoverSearch.BorderStyle==BorderStyle.None&&form.discoverSearch.Parent is RoundedSearchFrame,"Search fields retained native rectangular borders");form.SelectPrimaryPage(1);Application.DoEvents();AuditAssert(form.discoverPage.Visible&&!form.gameViewport.Visible&&!form.librarySidebar.Visible,"Discover did not replace Library");
            foreach(var size in new[]{new Size(1100,760),new Size(1600,1000)}){form.Size=size;Application.DoEvents();AuditAssert(form.discoverPage.Top>=form.topNavigation.Parent.Bottom,"Discover overlaps the header");AuditAssert(Math.Abs(form.topNavigation.Left+form.topNavigation.Width/2-form.topNavigation.Parent.ClientSize.Width/2)<=1,"Tabs are not centered");AuditAssert(form.featuredSurface!=null&&form.featuredSurface.Right<=form.discoverScroll.Content.Width,"Featured artwork clips horizontally");AuditAssert(form.featuredPrevious.Left>form.featuredSurface.Width/2&&form.featuredNext.Right<=form.featuredSurface.Width,"Featured arrows crowd the left project action");foreach(var card in form.discoverScroll.Content.Controls.OfType<DiscoverProjectCard>()){AuditAssert(card.Action.Width<card.Width/2&&card.Action.Right<=card.Width,"Card action still spans the listing");AuditAssert(Math.Abs(card.Artwork.Width/(double)card.Artwork.Height-1.93)<.03,"Card artwork stayed shallow while the card widened");AuditAssert(card.CategoryLabel.Bottom<card.Availability.Top,"Responsive artwork overlaps card text");}using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(root,"discover-"+size.Width+".png"));}}
            checks.Add("Centered tabs, quiet rounded search, right-side carousel controls and compact card actions fit both window sizes");form.discoverScroll.Content.Controls.OfType<DiscoverProjectCard>().First(c=>(string)c.Tag=="last-light").ActivateProject();AuditAssert(form.discoverDetailId=="last-light","Whole-card interaction did not open its detail page");var logo=form.discoverScroll.Content.Controls.OfType<DiscoverArtwork>().First();AuditAssert(logo.Artwork!=null&&logo.Fit=="contain","Last Light logo was missing or cropped");form.discoverDetailId="";form.RenderDiscover();checks.Add("Whole-card activation opens details, while Last Light keeps its full supplied logo");
            form.discoverSearch.Text="gacha";AuditAssert(form.discoverScroll.Content.Controls.OfType<DiscoverProjectCard>().Count()==1,"Search failed");form.discoverSearch.Clear();form.discoverCategoryValue="Coming soon";form.RenderDiscover();AuditAssert(form.discoverScroll.Content.Controls.OfType<DiscoverProjectCard>().Count()==1,"Coming-soon filter failed");form.discoverCategoryValue="All projects";form.RenderDiscover();var first=form.featuredProject.Id;form.featuredIndex++;form.ShowFeatured();AuditAssert(form.featuredProject.Id!=first,"Featured navigation did not change project");checks.Add("Search, category filtering, and featured navigation select the correct projects");
            form.ShowDiscoverProject("gacha-nebula-plus");AuditAssert(form.discoverScroll.Content.Controls.OfType<DiscoverArtwork>().First().Fit=="contain","Gacha artwork was still cropped by default");AuditAssert(form.discoverDetailId=="gacha-nebula-plus"&&!form.discoverFilters.Visible,"Detail page did not open");var actions=form.discoverScroll.Content.Controls.OfType<FlowLayoutPanel>().First(c=>Object.Equals(c.Tag,"detail-actions"));AuditAssert(actions.Controls[0].Enabled&&actions.Controls[0].Text=="Install","Ready Nebula release lacks the ZIP install action");form.ShowDiscoverProject("last-light");var upcoming=form.discoverScroll.Content.Controls.OfType<FlowLayoutPanel>().First(c=>Object.Equals(c.Tag,"detail-actions"));AuditAssert(!upcoming.Controls[0].Enabled,"Upcoming project exposed an install action");form.ShowDiscoverProject("gacha-nebula-plus");form.Size=new Size(1100,760);Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(root,"gacha-project-detail.png"));}
            form.discoverScroll.MoveTo(Int32.MaxValue);AuditAssert(form.discoverScroll.Offset==form.discoverScroll.Maximum,"Project scrolling did not clamp");form.discoverScroll.MoveTo(-1);AuditAssert(form.discoverScroll.Offset==0,"Project scrolling allowed a negative position");checks.Add("Detail pages show requirements/notes, keep upcoming actions disabled, and scroll within bounds");
            int count=state.Settings.CustomGames.Count;form.OpenDiscoverGame(2);form.SelectPrimaryPage(1);form.OpenDiscoverGame(2);AuditAssert(form.GameKind==2&&state.Settings.CustomGames.Count==count,"Library integration duplicated a project");form.SelectPrimaryPage(2);Application.DoEvents();AuditAssert(form.arcadePage.Visible&&!form.discoverPage.Visible,"Arcade navigation failed");form.SelectPrimaryPage(0);AuditAssert(form.gameViewport.Visible&&form.librarySidebar.Visible,"Library did not return");checks.Add("Existing project setup routes reuse Library entries; Arcade stays separate; no games launch");
            using(var art=GameArtwork.Load("Astera.Backgrounds.GachaNebulaPlus"))AuditAssert(art!=null&&art.Width>1000,"Gacha artwork missing");form.Close();
        }
        File.WriteAllText(Path.Combine(root,"result.json"),Engine.Json.Serialize(new{Passed=true,Checks=checks,GamesLaunched=false,RemoteRequests=false}));return 0;
    }catch(Exception error){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"failure.txt"),error.ToString());return 1;}}
}
}
